function system(){return toolbar('Explore a role')+`<div class="system-map"><div class="role-flow">${Object.entries(roles).map(([k,v],i)=>`<button class="role-node ${state.role===k?'selected':''}" data-action="role" data-value="${k}" aria-pressed="${state.role===k}"><span class="role-symbol">${['HQ','C','T','S','P'][i]}</span><strong>${v.title}</strong></button>`).join('')}</div><div class="role-detail"><div><div class="eyebrow">${roles[state.role].title}</div><h3>${roles[state.role].verb}</h3><p>${roles[state.role].text}</p></div><ul>${roles[state.role].links.map(x=>`<li><span>✓</span>${x}</li>`).join('')}</ul></div></div>`}
function protection(){const rights={hq:[true,true,true,true],teacher:[false,true,true,true],student:[false,true,false,false]}[state.accessRole];return toolbar('Private library → authorised delivery',resetBtn('protection'))+`<div class="access-layout"><div><label class="field-label" for="access-role">View as</label><select id="access-role" data-change="access-role"><option value="hq" ${state.accessRole==='hq'?'selected':''}>HQ curriculum owner</option><option value="teacher" ${state.accessRole==='teacher'?'selected':''}>Centre teacher</option><option value="student" ${state.accessRole==='student'?'selected':''}>Assigned student</option></select><div class="permission-list">${['Open original source file','View assigned / permitted pages','Open teacher answer key','Request an approved print'].map((x,i)=>`<div><span>${x}</span><strong class="${rights[i]?'allowed':'restricted'}">${rights[i]?'Allowed':'Restricted'}</strong></div>`).join('')}</div><button class="secondary-button" data-action="original-access">Try original-file access</button></div><div class="print-path"><div class="print-path-step"><span>01</span><div><strong>601A · approved version 2</strong><p>Check the account, centre and assignment.</p></div></div><div class="print-path-step"><span>02</span><div><strong>Tsuen Wan · authorised printer</strong><p>A managed device receives the approved job.</p></div></div><div class="print-path-step"><span>03</span><div><strong>Record the issued copy</strong><p>Link a reference to this worksheet and request.</p></div></div><button class="primary-button" data-action="print-request" ${!rights[3]?'disabled':''}>Simulate print request <span>→</span></button>${state.printed?`<div class="print-record"><span class="tag green">Simulated job accepted</span><strong>601A · MC-${String(state.printCount).padStart(6,'0')}</strong><p>Tsuen Wan · ${state.accessRole==='hq'?'HQ owner':'Teacher'} · approved printer</p><div class="dot-rule" aria-hidden="true">${Array.from({length:30},(_,i)=>`<i class="${(i+state.printCount)%3?'filled':''}"></i>`).join('')}</div><small>Illustrative pattern. No printer or watermark decoder is connected.</small></div>`:''}</div></div>`}
function library(){const stage=state.libStage;const stages=[['original','Original page'],['reusable','Reusable question'],['editable','Editable question']];return toolbar('P6 / Decimals / 601A',resetBtn('library'))+`<div class="segmented stage-tabs" aria-label="Conversion stage">${stages.map(([v,l])=>`<button data-action="library-stage" data-value="${v}" class="${stage===v?'active':''}" aria-pressed="${stage===v}">${l}</button>`).join('')}</div><div class="library-layout"><div class="source-preview">${stage==='original'?questionPaper(`<button class="extract-button" data-action="library-stage" data-value="reusable">Select question 2 ↗</button>`):stage==='reusable'?`<div class="question-cutout"><span class="field-label">Selected from 601A · page 1</span><div class="large-equation">8.4 ÷ 4 = <span class="answer-line"></span></div><div class="paper-work"></div></div>`:`<div class="editable-question"><span class="field-label">Question Q-601A-01</span><label for="decimal-value">Dividend</label><input id="decimal-value" type="number" step="0.1" min="0" max="999" value="${esc(state.libValue)}" data-change="dividend"><div class="large-equation" id="equation-preview">${esc(state.libValue)} ÷ 3 = <span class="answer-line"></span></div><div class="answer-preview" id="answer-preview">Teacher answer: ${Number((Number(state.libValue)/3).toFixed(2))}</div><div class="paper-work"></div></div>`}</div><div class="library-info"><span class="stage-number">${stage==='original'?'01':stage==='reusable'?'02':'03'}</span><h3>${stage==='original'?'Keep the exact teaching page.':stage==='reusable'?'Make a question reusable.':'Give the question structure.'}</h3><p>${stage==='original'?'Teachers can already find, assign and print this page. Search information sits alongside the faithful original layout.':stage==='reusable'?'The selected question becomes an image block, with its source and teaching tags recorded. It can be combined with new digital content.':'The numbers and mathematical expression are editable. Change the dividend to see the question and its calculated answer update.'}</p><dl class="metadata"><div><dt>Grade / topic</dt><dd>P6 / Decimal division</dd></div><div><dt>Source</dt><dd>601A · version 2 · page 1</dd></div><div><dt>Publication</dt><dd>${stage==='editable'?'Draft · review required':'Approved source example'}</dd></div></dl>${stage==='reusable'?`<button class="primary-button" data-action="use-extracted">Add to worksheet studio →</button>`:''}${stage==='editable'?'<p class="small">This arithmetic example is calculated directly. General conversion and question validation still require review.</p>':''}</div></div>`}
