function teacher(){const p6=state.grade==='P6';return toolbar('Progress chart',resetBtn('teacher'))+`<div class="teacher-workbench"><aside class="class-strip"><div class="class-nav"><button aria-label="Previous class" data-action="teacher-class" data-value="previous">‹</button><span>${state.teacherClass==='today'?'Wed 30 Sept':'Mon 28 Sept'}<strong>16:00–17:00</strong></span><button aria-label="Next class" data-action="teacher-class" data-value="today">›</button></div><button class="student-select active"><strong>Alex Chan</strong><span>P6 · MC-0105</span></button><div class="class-other"><span>Jamie Lee</span><small>P6</small></div><div class="class-other"><span>Robin Wong</span><small>P5</small></div><div class="class-strip-foot">Teacher · Koko<br>Sample class</div></aside><div class="chart-area"><div class="chart-top"><div><strong>Alex Chan</strong><span>P6</span></div><label>Worksheets <select data-change="grade" aria-label="Worksheet grade"><option ${p6?'selected':''}>P6</option><option ${!p6?'selected':''}>P3</option></select></label></div><div class="chart-scroll"><table class="progress-table"><thead><tr><th>Topic</th><th>Math 1–6</th><th>EXCEL</th><th>Revision</th></tr></thead><tbody><tr class="term-row"><td colspan="4">First term</td></tr>${(p6?topics:[['301','5-digit numbers','ABCDER'],['302','Kilometres','ABCR'],['303','Millimetres','ABCDER'],['304','Multiplication: 2-digit × 1-digit','ABCR'],['305','Multiplication: 3-digit × 1-digit','ABCDR']]).map(([code,title,letters],i)=>`<tr><th><span>${code}</span>${title}</th><td><div class="worksheet-buttons">${[...letters].map((letter,j)=>{const id=code+letter;const sent=state.assigned.some(a=>a.code===id);return `<button data-action="select-sheet" data-value="${id}" aria-label="Select worksheet ${id}" aria-pressed="${state.selected.has(id)}" class="${state.selected.has(id)?'chosen':sent?'sent':i===0&&j===1?'done':''}">${letter}</button>`}).join('')}</div></td><td><div class="worksheet-buttons"><button data-action="select-sheet" data-value="${code}-EX-A" aria-label="Select EXCEL ${code} A" aria-pressed="${state.selected.has(code+'-EX-A')}" class="${state.selected.has(code+'-EX-A')?'chosen':''}">A</button></div></td><td><div class="worksheet-buttons"><button data-action="select-sheet" data-value="${p6?'6':'3'}A0${i+1}-A1" aria-label="Select revision ${i+1} A1" class="${state.selected.has(`${p6?'6':'3'}A0${i+1}-A1`)?'chosen':''}">A1</button><button data-action="select-sheet" data-value="${p6?'6':'3'}A0${i+1}-B1" aria-label="Select revision ${i+1} B1" class="${state.selected.has(`${p6?'6':'3'}A0${i+1}-B1`)?'chosen':''}">B1</button></div></td></tr>`).join('')}${state.builderPublished?`<tr><th><span>NEW</span>${esc(state.builderTitle||'Division of decimals')}</th><td colspan="3"><button class="secondary-button small-button" data-action="select-sheet" data-value="CUSTOM-01">${state.selected.has('CUSTOM-01')?'Selected ✓':'Select studio worksheet'}</button></td></tr>`:''}</tbody></table></div><div class="chart-legend"><span><i class="legend-square"></i>Not sent</span><span><i class="legend-square blue"></i>Sent</span><span><i class="legend-square green"></i>Completed</span></div><div class="assignment-bar"><div><strong>${state.selected.size} selected</strong><small>${state.selected.size?[...state.selected].join(', '):'Choose worksheet boxes to send'}</small></div><select aria-label="Assignment type" data-change="assignment-type"><option ${state.assignmentType==='Classwork'?'selected':''}>Classwork</option><option ${state.assignmentType==='Homework'?'selected':''}>Homework</option></select><button class="primary-button" data-action="send-student" ${!state.selected.size?'disabled':''}>Send to student →</button></div>${state.assigned.length?`<div class="inline-success">${state.assigned.length} worksheet${state.assigned.length>1?'s':''} sent. <a href="#student">Open Alex’s binder →</a></div>`:''}</div></div>`}
function binder(){const extra=state.assigned.filter(a=>a.code!=='601A');return toolbar('Student binder · Alex Chan',`<button class="text-button" data-action="open-workspace">Try writing full screen ↗</button>`)+`<div class="binder" lang="zh-HK"><div class="binder-tabs" role="group" aria-label="工作分類"><button class="${state.binder==='past'?'active':''}" data-action="binder-tab" data-value="past"><span>✓</span>已完成</button><button class="${state.binder==='current'?'active':''}" data-action="binder-tab" data-value="current"><span>✎</span>現在做</button><button class="${state.binder==='future'?'active':''}" data-action="binder-tab" data-value="future"><span>▣</span>稍後做</button></div><div class="binder-content">${state.binder==='current'?`<div class="binder-greeting"><h3>Alex，準備好嗎？</h3><p>選一份工作紙，開始做吧。</p></div><div class="binder-sheets"><button class="sheet-cover correction" data-action="open-workspace" data-value="601A"><span class="sheet-fold"></span><small>訂正</small><strong>601A</strong><span>小數除法</span><i>繼續做 →</i></button><button class="sheet-cover" data-action="open-workspace" data-value="602A"><span class="sheet-fold"></span><small>課堂練習</small><strong>602A</strong><span>除以小數</span><i>打開 →</i></button>${extra.map(a=>`<button class="sheet-cover new-sheet" data-action="open-workspace" data-value="${esc(a.code)}"><span class="sheet-fold"></span><small>老師剛送來的</small><strong>${esc(a.code)}</strong><span>${a.type==='Homework'?'功課':'課堂練習'}</span><i>打開 →</i></button>`).join('')}</div>`:state.binder==='past'?`<div class="binder-greeting"><h3>看看你完成的練習</h3><p>每一份，都是你的進步。</p></div><div class="binder-sheets"><button class="sheet-cover completed" data-action="open-completed"><small>已完成 ✓</small><strong>600R</strong><span>溫習練習</span><i>重溫 →</i></button></div>`:`<div class="locked-folder"><span class="lock-glyph">▣</span><h3>老師為你準備好了</h3><p>等老師開放後，就可以開始做。</p><div><span>603A</span><span>604B</span></div></div>`}</div><div class="binder-bottom"><span>我的學習夾</span><span>MathConcept</span></div></div>`}
function workspace(code='601A',completed=false){state.worksheet=code;const custom=code==='CUSTOM-01';const saved=state.assigned.find(a=>a.code===code)?.worksheet||state.publishedWorksheet;const qs=custom?(saved?.questions||state.builder).filter(x=>!x.space):[{prompt:'12.6 ÷ 3 =',answer:'4.2'},{prompt:'8.4 ÷ 4 =',answer:'2.1'},{prompt:'9.6 ÷ 4 =',answer:'2.4'}];return `<div class="student-workspace" lang="zh-HK"><div class="writing-tools"><span>${esc(code)} · ${completed?'已完成':'小數除法'}</span><div><button class="secondary-button small-button" data-action="undo-ink" ${completed?'disabled':''}>復原</button><button class="secondary-button small-button" data-action="clear-ink" ${completed?'disabled':''}>清除</button><button class="primary-button small-button" data-action="save-ink">${completed?'返回':'儲存'}</button></div></div><div class="writing-page"><div class="writing-header"><strong>MathConcept</strong><span>姓名：Alex Chan</span></div><h3>${custom?esc(saved?.title||'Division of decimals'):'小數除法'}</h3><p>請寫出計算過程。</p><div class="ink-surface"><div class="writing-questions">${qs.map((q,i)=>`<div class="writing-question"><strong>${i+1}. &nbsp; ${esc(q.prompt)} ${completed?esc(q.answer):'________'}</strong><div class="writing-space"></div></div>`).join('')}</div><canvas id="ink-canvas" aria-label="用手指或觸控筆書寫的空間" data-code="${esc(code)}" ${completed?'data-readonly="true"':''}></canvas></div><p class="writing-foot">${completed?'老師已批改 ✓':'示範：筆跡只保留於本次瀏覽，重新載入後會清除。'}</p></div></div>`}
function operations(){const s=state.schedule;const locations={wed:'Wednesday · 16:00',thu:'Thursday · 16:00',fri:'Friday · 16:00'};return toolbar('Koko · 28 Sept – 4 Oct 2026',resetBtn('operations'))+`<div class="schedule-example"><div class="mini-calendar"><div class="calendar-head"><span></span><strong>WED <b>30</b></strong><strong>THU <b>1</b></strong><strong>FRI <b>2</b></strong></div>${[15,16,17].map(hour=>`<div class="calendar-row"><span>${hour}:00</span>${['wed','thu','fri'].map(day=>`<div class="calendar-cell ${hour===15?'off':''}" data-drop="${day}" data-hour="${hour}" ${hour===16?`role="button" tabindex="0" aria-label="Move selected lesson to ${locations[day]}"`:''}>${hour===16&&(s.lesson===day||day==='wed'&&s.cancelled)?`<button class="lesson-strip ${s.cancelled&&day==='wed'?'cancelled':''} ${state.lessonSelected?'selected':''}" draggable="${!(s.cancelled&&day==='wed')}" ${s.cancelled&&day==='wed'?'disabled':''} data-action="select-lesson" aria-label="Select Alex Chan’s lesson">Alex Chan <small>(P6)</small></button>`:''}${hour===17&&day==='thu'?'<span class="lesson-strip secondary-lesson">Jamie Lee <small>(P6)</small></span>':''}</div>`).join('')}</div>`).join('')}<p class="calendar-hint">Drag Alex’s lesson into another 16:00 slot or the leave bin. You can also select the lesson, then click a destination.</p></div><aside class="schedule-rail"><button class="leave-bin ${s.pending?'has-pending':''}" data-action="leave-bin" data-drop="bin"><span>▱</span><strong>Leave bin</strong><small>Arrange with the parent later</small></button>${s.pending?`<div class="pending-strip">Alex Chan (P6)<span>30 Sept</span></div><p class="small">Leave recorded. CS contacts the parent to arrange the make-up.</p><button class="secondary-button small-button" data-action="arrange-makeup">Arrange agreed time</button>`:'<p class="small">No pending make-ups.</p>'}<div class="parent-message" lang="zh-HK"><strong>家長收到的訊息</strong><p>${s.pending?'請假已確認。你可提供希望補堂的日期，CS 將聯絡你完成安排。補堂時間尚未確認。':'課堂安排以中心確認為準。'}</p></div></aside></div><details class="regular-change"><summary>Change a regular schedule <span>→</span></summary><div class="regular-form"><div><label for="change-duration">Duration</label><select id="change-duration" data-change="move-mode"><option value="one" ${state.moveMode==='one'?'selected':''}>Permanent · from 1 Oct</option><option value="temporary" ${state.moveMode==='temporary'?'selected':''}>Temporary · 1–21 Oct</option></select></div><div><label>New regular schedule</label><div class="fixed-control">Thursday · 16:00–17:00</div></div><button class="secondary-button" data-action="review-schedule">Review lesson count</button></div>${state.scheduleReview?`<div class="lesson-impact"><div><span>Remaining lessons in October</span><strong>${state.moveMode==='temporary'?'4 → 4':'4 → 5'}</strong><p>${state.moveMode==='temporary'?'Three Thursday lessons, then back to Wednesday on 28 Oct.':'Changing from Wednesday to Thursday adds one October lesson.'}</p></div>${state.moveMode==='temporary'?`<button class="primary-button" data-action="confirm-schedule" data-value="temporary">Confirm temporary change</button>`:`<div class="impact-actions"><button class="primary-button" data-action="confirm-schedule" data-value="allow">Allow the extra lesson</button><button class="secondary-button" data-action="confirm-schedule" data-value="keep">Keep 4 lessons</button></div>`}</div>`:''}${state.scheduleApplied?`<div class="inline-success">${esc(state.scheduleApplied)}</div>`:''}</details>`}
function invoiceFilter(){return state.invoices.filter(x=>x.status==={waiting:'waiting',review:'review',issued:'issued'}[state.billTab]&&(!state.search||[x.student,x.studentNo,x.id].join(' ').toLowerCase().includes(state.search.toLowerCase()))&&(state.charge==='all'||x.type===state.charge)&&(state.month==='all'||x.month===state.month)).sort((a,b)=>state.billTab==='issued'?b.month.localeCompare(a.month):a.date.localeCompare(b.date))}
function billing(){const tabs=[['waiting','Waiting for parent'],['review','Centre review'],['issued','Receipt issued'],['audit','Final audit']];return toolbar('Billing & reconciliation',`<div class="billing-controls"><label class="toggle-label"><input type="checkbox" id="auto-sent" data-change="auto-sent" ${state.autoSent?'checked':''}><span class="switch-visual"></span>Auto-sent</label>${resetBtn('billing')}</div>`)+`<div class="billing-tabs">${tabs.map(([v,l])=>`<button data-action="bill-tab" data-value="${v}" class="${state.billTab===v?'active':''}" aria-pressed="${state.billTab===v}">${l}${v!=='audit'?`<span>${state.invoices.filter(i=>i.status===v).length}</span>`:''}</button>`).join('')}</div>${state.billTab==='audit'?audit():`<div class="billing-filter"><input type="search" aria-label="Search invoices" placeholder="Student, student no. or invoice" value="${esc(state.search)}" data-change="bill-search"><select aria-label="Charge type" data-change="charge-filter"><option value="all">All charges</option><option ${state.charge==='Tuition'?'selected':''}>Tuition</option><option ${state.charge==='Assessment'?'selected':''}>Assessment</option></select><select aria-label="Billing month" data-change="month-filter"><option value="all">All billing months</option>${[['2026-07','July 2026'],['2026-09','September 2026'],['2026-11','November 2026']].map(([v,l])=>`<option value="${v}" ${state.month===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="invoice-list">${invoiceFilter().map(x=>`<div class="invoice-row"><div><strong>${x.student}</strong><small>${x.studentNo} · ${x.id}</small><small>${x.parent} · Parent</small></div><div><strong>${x.type}</strong><small>${x.period}</small>${x.replacement?'<span class="replacement">Waiting for replacement proof</span>':''}</div><div class="invoice-amount"><strong>${money(x.amount)}</strong><small class="${x.status==='waiting'&&x.deadline<'2026-09-22'?'overdue':''}">${x.status==='waiting'?'Due ':x.status==='review'?'Uploaded ':''}${x.date}</small>${x.reminded?'<small>Reminded just now</small>':''}</div><button class="${x.status==='review'?'primary-button':'secondary-button'} small-button" data-action="${x.status==='review'?'review-payment':x.status==='issued'?'view-receipt':'remind'}" data-id="${x.id}" ${x.reminded?'disabled':''}>${x.status==='review'?'Review payment':x.status==='issued'?'View receipt':x.reminded?'Reminder sent':x.replacement?'Request new proof':'Remind parent'}</button></div>`).join('')||'<div class="empty-state">No invoices match this view.</div>'}</div><div class="list-footer"><span>${invoiceFilter().length} invoice${invoiceFilter().length!==1?'s':''} · sample list</span><span>Page 1 of 1</span></div><div class="sample-proof"><div><strong>Try the parent’s next step</strong><p>Submit sample proof for Alex’s outstanding September invoice.</p></div><button class="secondary-button" data-action="submit-proof" ${state.invoices[0].status!=='waiting'?'disabled':''}>${state.invoices[0].status==='waiting'?'Submit sample proof':state.invoices[0].status==='issued'?'Receipt auto-sent ✓':'In review queue ✓'}</button></div>`}`}
function audit(){const receipts=state.invoices.filter(i=>i.status==='issued'&&i.month!=='2026-07');const matched=receipts.filter(i=>['FPS-841902','FPS-629815'].includes(i.reference));const unconfirmed=receipts.filter(i=>!['FPS-841902','FPS-629815'].includes(i.reference));return `<div class="audit-view"><div class="audit-intro"><div><h3>September statement</h3><p>Compare bank credits against receipts issued. Review the exceptions before closing the period.</p></div><button class="primary-button" data-action="load-statement">${state.audit?'Reload sample statement':'Load sample statement'}</button></div>${state.audit?`<div class="audit-stats"><div><strong>${matched.length}</strong><span>Matched receipts</span></div><div><strong>${unconfirmed.length}</strong><span>Receipt without a bank match</span></div><div><strong>${3-matched.length}</strong><span>Credits needing allocation</span></div></div><div class="audit-lines">${matched.map(i=>`<div><span class="audit-icon">✓</span><div><strong>${i.student} · ${money(i.amount)}</strong><small>${i.receipt} ↔ ${i.reference} · bank posted 21 Sept</small></div><span class="tag green">Matched</span></div>`).join('')}${unconfirmed.map(i=>`<div><span class="audit-icon amber">!</span><div><strong>${i.student} · ${money(i.amount)}</strong><small>${i.receipt} · no matching credit in this statement</small></div><span class="tag amber">Check timing / evidence</span></div>`).join('')}${!matched.some(i=>i.reference==='FPS-841902')?`<div><span class="audit-icon amber">!</span><div><strong>Chris Chan · HK$1,600</strong><small>FPS-841902 · posted 21 Sept · corresponding proof still awaiting confirmation</small></div><button class="text-button" data-action="bill-tab" data-value="review">Go to review →</button></div>`:''}<div><span class="audit-icon amber">!</span><div><strong>Unallocated bank credit · HK$500</strong><small>FPS-772204 · posted 22 Sept · no matching receipt</small></div><button class="text-button" data-action="audit-exception">Inspect →</button></div></div><p class="audit-note">Sample statement: three credits totalling HK$2,400. The example matches exact references and amounts; production matching needs agreed rules for ambiguity, fees, split payments and date differences.</p>`:'<div class="audit-empty"><span>▤</span><h3>Bring the bank record into the picture.</h3><p>This example includes matching credits and an extra credit that needs staff attention.</p></div>'}</div>`}
function reviewInvoice(id){const i=state.invoices.find(x=>x.id===id);return `<div class="review-comparison"><article class="invoice-document"><span class="field-label">INVOICE</span><h3>${i.id}</h3><p>${i.student} · ${i.studentNo}</p><dl class="metadata"><div><dt>Charge</dt><dd>${i.type}</dd></div><div><dt>Period</dt><dd>${i.period}</dd></div><div><dt>Due</dt><dd>${i.deadline}</dd></div></dl><div class="document-total">${money(i.amount)}</div></article><article class="proof-document"><span class="field-label">SAMPLE PAYMENT PROOF</span><div class="proof-check">✓</div><h3>Transfer submitted</h3><strong class="proof-amount">${money(i.amount)}</strong><dl class="metadata"><div><dt>Payer</dt><dd>${i.parent}</dd></div><div><dt>Recipient</dt><dd>MathConcept · sample account</dd></div><div><dt>Method</dt><dd>FPS</dd></div><div><dt>Initiated</dt><dd>${i.initiated||'21 Sept 2026 · 11:02'}</dd></div><div><dt>Reference</dt><dd>${i.reference||'FPS-330108'}</dd></div></dl></article></div><div class="review-actions"><button class="primary-button" data-action="confirm-payment" data-id="${i.id}">Confirm payment & issue receipt</button><button class="secondary-button" data-action="return-proof" data-id="${i.id}">Return proof for resubmission</button></div><p class="small">Illustrative evidence only. Confirmation here changes the sample invoice, not a live financial record.</p>`}
function franchise(){const hq=state.franchise==='hq';return toolbar('Network permissions',`<div class="segmented"><button data-action="franchise" data-value="hq" class="${hq?'active':''}">HQ</button><button data-action="franchise" data-value="centre" class="${!hq?'active':''}">Centre</button></div>`)+`<div class="franchise-layout"><div><div class="eyebrow">${hq?'HEAD OFFICE':'TSUEN WAN CENTRE'}</div><h3>${hq?'Set the shared standard.':'Run your centre with confidence.'}</h3><p>${hq?'Publish approved collections and grant centre access. Local staff work within those permissions.':'Teachers use approved materials and staff coordinate their own students, lessons and parent requests.'}</p><div class="centre-stack">${(hq?['Tsuen Wan','Hang Hau','Overseas pilot centre']:['Tsuen Wan']).map((x,i)=>`<div><span class="centre-symbol">${i===2?'↗':'M'}</span><div><strong>${x}</strong><small>${i===2?'Proposed rollout · scope to agree':'Curriculum access by programme'}</small></div></div>`).join('')}</div></div><div class="governance-table"><div><strong>Capability</strong><strong>${hq?'HQ':'Centre'}</strong></div>${[['Publish a master worksheet',hq],['Manage curriculum access across centres',hq],['Assign approved material',true],['Manage this centre’s students',true],['View another centre’s student records',hq],['Export original curriculum files',hq]].map(([label,yes])=>`<div><span>${label}</span><span class="${yes?'allowed':'restricted'}">${yes?'Permitted':'Restricted'}</span></div>`).join('')}</div></div>`}
const phases=[{label:'Discover',title:'Understand the real collection and routines.',body:'Inventory a representative sample of materials and operational records. Confirm the authoritative versions, essential workflows, device requirements and owners.',items:['Material formats, page counts and exceptions','Sample schedules, balances and bank exports','Pilot scope, responsibilities and success measures'],gate:'An agreed scope and a realistic migration estimate.'},{label:'Build the pilot',title:'Make one centre’s core journeys work.',body:'Implement the agreed library, teaching, student, parent and administration flows. Start with a limited curriculum set and the selected devices.',items:['Role permissions and controlled content delivery','Save, retry, review and correction flows','Training, migration checks and support arrangements'],gate:'Staff can complete the agreed journeys with validated data.'},{label:'Validate',title:'Test the parts a screen cannot prove.',body:'Run the pilot with real staff routines. Measure content fidelity, writing behaviour, scheduling consistency and financial exceptions.',items:['Print success, failure and retry behaviour','Bank matching, duplicate imports and allocations','Access boundaries, recovery and launch blockers'],gate:'Owners accept the evidence and resolve launch blockers.'},{label:'Expand',title:'Roll out what the pilot has established.',body:'Move additional materials and centres in manageable batches. Extend native authoring and AI assistance after their content checks are proven.',items:['Batch migration with exception reports','Centre onboarding and support coverage','Overseas policies, languages and curriculum entitlements'],gate:'Each centre is ready before its access and operations go live.'}];
function rollout(){const p=phases[state.phase];return toolbar('Delivery sequence · dates to agree')+`<div class="phase-track">${phases.map((x,i)=>`<button class="${state.phase===i?'active':''}" data-action="phase" data-value="${i}"><span>${String(i+1).padStart(2,'0')}</span><strong>${x.label}</strong></button>`).join('')}</div><div class="phase-content"><div><h3>${p.title}</h3><p>${p.body}</p></div><ul>${p.items.map(x=>`<li>${x}</li>`).join('')}</ul><div class="phase-gate"><span>PROCEED WHEN</span><strong>${p.gate}</strong></div></div>`}
const renderers={system,protection,library,authoring,teacher,student:binder,operations,billing,franchise,rollout};
export function renderDemo(id){const el=$('#demo-'+id);if(el&&renderers[id])el.innerHTML=renderers[id]()}
function sync(ids){ids.forEach(renderDemo)}
function close(){$('#detail-dialog').close()}
function refreshInk(){const canvas=$('#ink-canvas');if(!canvas)return;const r=canvas.getBoundingClientRect(),dpr=window.devicePixelRatio||1;canvas.width=r.width*dpr;canvas.height=r.height*dpr;const ctx=canvas.getContext('2d');ctx.scale(dpr,dpr);ctx.lineCap='round';ctx.lineJoin='round';ctx.lineWidth=2.4;ctx.strokeStyle='#273c6b';for(const stroke of state.strokes[canvas.dataset.code]||[]){ctx.beginPath();stroke.forEach(([x,y],i)=>i?ctx.lineTo(x*r.width,y*r.height):ctx.moveTo(x*r.width,y*r.height));ctx.stroke()}}
function setupInk(){const c=$('#ink-canvas');if(!c)return;refreshInk();if(c.dataset.readonly)return;const code=c.dataset.code;state.strokes[code]??=[];let drawing=false;const point=e=>{const r=c.getBoundingClientRect();return[(e.clientX-r.left)/r.width,(e.clientY-r.top)/r.height]};c.addEventListener('pointerdown',e=>{if(e.pointerType==='mouse'&&e.button!==0)return;e.preventDefault();drawing=true;c.setPointerCapture(e.pointerId);state.strokes[code].push([point(e)])});c.addEventListener('pointermove',e=>{if(!drawing)return;state.strokes[code].at(-1).push(point(e));refreshInk()});const end=()=>{drawing=false;refreshInk()};c.addEventListener('pointerup',end);c.addEventListener('pointercancel',end)}
function showWorkspace(code,completed=false){openDialog(completed?'已完成的工作紙':'工作紙',workspace(code||'601A',completed),'workspace-dialog');requestAnimationFrame(setupInk)}
export function initDemos(helpers){notify=helpers.notify;openDialog=helpers.openDialog;Object.keys(renderers).forEach(renderDemo);
 document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,v=b.dataset.value,id=b.dataset.id;
  if(a==='role'){state.role=v;renderDemo('system')}
  if(a==='original-access'){openDialog('Original-file access',state.accessRole==='hq'?'<div class="access-result allowed"><h3>Authorised for the HQ curriculum owner</h3><p>In production this action would require an authorised account and would be logged. No original file is included in this example.</p></div>':'<div class="access-result restricted"><h3>The original stays private.</h3><p>This role can use permitted page representations. It cannot retrieve the original source file.</p></div>')}
  if(a==='print-request'){state.printCount++;state.printed=true;renderDemo('protection')}
  if(a==='library-stage'){state.libStage=v;renderDemo('library')}
  if(a==='use-extracted'){state.builder.push({id:Date.now(),prompt:'8.4 ÷ 4 =',answer:'2.1',source:true});state.builderPublished=false;renderDemo('authoring');notify('Source question added to the worksheet studio.');location.hash='authoring'}
  if(a==='add-question'||a==='add-bank'||a==='add-space'){state.builder.push({id:Date.now(),...(a==='add-bank'?bankQuestion:a==='add-space'?{space:true}:{prompt:'24.8 ÷ 4 =',answer:'6.2'})});state.builderPublished=false;renderDemo('authoring')}
  if(a==='block-remove'){state.builder=state.builder.filter(q=>String(q.id)!==id);state.builderPublished=false;renderDemo('authoring')}
  if(a==='block-up'){let i=state.builder.findIndex(q=>String(q.id)===id);if(i>0)[state.builder[i-1],state.builder[i]]=[state.builder[i],state.builder[i-1]];state.builderPublished=false;renderDemo('authoring')}
  if(a==='builder-view'){state.builderView=v;renderDemo('authoring')}
  if(a==='ai-draft'){openDialog('AI-assisted draft · prepared example',`<p class="reference-lead">A proposed response to: “Draft three P6 decimal-division questions with exact answers.”</p><div class="ai-draft-list">${[[18.6,3],[25.2,6],[16.8,4]].map(([n,d])=>`<div><strong>${n} ÷ ${d} = _____</strong><span>Calculated answer: ${(n/d).toFixed(1)}</span></div>`).join('')}</div><p>These are prepared sample questions. A production assistant would retrieve permitted examples, generate a draft and run agreed checks before author review.</p><div class="review-actions"><button class="primary-button" data-action="accept-ai">Add these draft questions</button></div>`)}
  if(a==='accept-ai'){[[18.6,3],[25.2,6],[16.8,4]].forEach(([n,d],i)=>state.builder.push({id:Date.now()+i,prompt:`${n} ÷ ${d} =`,answer:(n/d).toFixed(1)}));state.builderPublished=false;close();renderDemo('authoring');notify('Three draft questions added. Review before publishing.')}
  if(a==='publish-builder'){openDialog('Review worksheet before publishing',`<p class="reference-lead">${esc(state.builderTitle||'Division of decimals')} · ${state.builder.filter(x=>!x.space).length} questions</p><div class="ai-draft-list">${state.builder.filter(x=>!x.space).map(q=>`<div><strong>${esc(q.prompt)}</strong><span>Answer: ${esc(q.answer)}</span></div>`).join('')}</div><p>Check the questions, answers, working space and tablet/A4 previews. Publishing here adds the sample worksheet to the teacher chapter.</p><label class="review-checkbox"><input type="checkbox" id="publish-check"> I have reviewed this sample worksheet.</label><button class="primary-button" data-action="confirm-publish">Publish sample worksheet</button>`)}
  if(a==='confirm-publish'){if(!$('#publish-check').checked){notify('Please review the worksheet and tick the confirmation.');return}state.builderPublished=true;state.publishedWorksheet={title:state.builderTitle||'Division of decimals',questions:state.builder.map(q=>({...q}))};close();sync(['authoring','teacher']);notify('Published to the sample teacher library.');}
  if(a==='teacher-class'){state.teacherClass=v;renderDemo('teacher')}
  if(a==='select-sheet'){state.selected.has(v)?state.selected.delete(v):state.selected.add(v);renderDemo('teacher')}
  if(a==='send-student'){for(const code of state.selected)if(!state.assigned.some(q=>q.code===code))state.assigned.push({code,type:state.assignmentType,worksheet:code==='CUSTOM-01'?structuredClone(state.publishedWorksheet):null});state.selected.clear();state.binder='current';sync(['teacher','student']);notify('Worksheets sent to Alex’s current-work binder.')}
  if(a==='binder-tab'){state.binder=v;renderDemo('student')}
  if(a==='open-workspace')showWorkspace(v);
  if(a==='open-completed')showWorkspace('600R',true);
  if(a==='undo-ink'){state.strokes[state.worksheet]?.pop();refreshInk()}
  if(a==='clear-ink'){state.strokes[state.worksheet]=[];refreshInk()}
  if(a==='save-ink'){close();notify('工作已儲存於本次示範。')}
  if(a==='select-lesson'){state.lessonSelected=true;renderDemo('operations');notify('Lesson selected. Choose another 16:00 slot or the leave bin.')}
  if(a==='leave-bin'){if(!state.lessonSelected&&!state.schedule.pending){notify('Select Alex’s lesson first, or drag it here.');return}if(!state.schedule.pending)recordLeave()}
  if(a==='arrange-makeup'){openDialog('Confirm the time agreed with the parent',`<p class="reference-lead">Alex Chan · leave on 30 September</p><label class="field-label" for="makeup-day">Agreed make-up time</label><select id="makeup-day"><option value="thu">Thursday 1 Oct · 16:00</option><option value="fri">Friday 2 Oct · 16:00</option></select><p class="small" style="margin:16px 0">This example assumes staff have already contacted the parent. Submitting a preference alone never books the lesson.</p><button class="primary-button" data-action="confirm-makeup">Confirm agreed make-up</button>`)}
  if(a==='confirm-makeup'){state.schedule={lesson:$('#makeup-day').value,cancelled:true,pending:false};state.lessonSelected=false;close();renderDemo('operations');notify('The agreed make-up is now on the sample schedule.')}
  if(a==='review-schedule'){state.scheduleReview=true;state.scheduleApplied=false;renderDemo('operations');$('#demo-operations .regular-change').open=true}
  if(a==='confirm-schedule'){state.scheduleApplied=v==='temporary'?'Temporary change confirmed: Thu 1, 8 and 15 Oct, then Wed 28 Oct.':v==='allow'?'Change confirmed with 5 October lessons. The extra lesson and linked document revision are recorded.':'Change confirmed with 4 October lessons. The extra Thursday is excluded.';state.scheduleReview=false;renderDemo('operations');$('#demo-operations .regular-change').open=true}
  if(a==='bill-tab'){state.billTab=v;renderDemo('billing')}
  if(a==='review-payment')openDialog('Review payment',reviewInvoice(id));
  if(a==='confirm-payment'){const i=state.invoices.find(x=>x.id===id);i.status='issued';i.date='22 Sept · just now';i.receipt='R-'+i.id.slice(4);close();renderDemo('billing');notify('Payment confirmed and sample receipt issued. Your list is preserved.')}
  if(a==='return-proof'){const i=state.invoices.find(x=>x.id===id);openDialog('Request replacement proof',`<p class="reference-lead">${i.student} · ${i.id}</p><p>Ask for clearer evidence of the existing payment. This does not ask the parent to pay again.</p><label class="field-label" for="return-reason">Reason</label><textarea id="return-reason" rows="3" placeholder="For example: the recipient details are cut off." required></textarea><p id="return-error" class="form-error" role="alert"></p><button class="primary-button" data-action="confirm-return" data-id="${id}">Send resubmission request</button>`)}
  if(a==='confirm-return'){const reason=$('#return-reason').value.trim();if(!reason){$('#return-error').textContent='Enter a reason before returning the proof.';$('#return-reason').focus();return}const i=state.invoices.find(x=>x.id===id);i.status='waiting';i.date=new Date(i.deadline+'T12:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'});i.replacement=true;i.reason=reason;close();renderDemo('billing');notify('Replacement proof requested. The parent is not asked to pay again.')}
  if(a==='view-receipt'){const i=state.invoices.find(x=>x.id===id);openDialog('Sample receipt',`<div class="receipt-view"><img src="assets/mathconcept-logo.png" alt="MathConcept"><span class="field-label">RECEIPT · SAMPLE</span><h3>${i.receipt}</h3><dl class="metadata"><div><dt>Student</dt><dd>${i.student} · ${i.studentNo}</dd></div><div><dt>Invoice</dt><dd>${i.id}</dd></div><div><dt>Charge</dt><dd>${i.period}</dd></div><div><dt>Issued</dt><dd>${i.date}</dd></div></dl><div class="document-total">${money(i.amount)}</div><p class="small">${i.auto?'Issued under the sample Auto-sent policy. ':''}Bank reconciliation is tracked separately. This is an illustrative document, not a valid receipt.</p></div>`)}
  if(a==='remind'){const i=state.invoices.find(x=>x.id===id);i.reminded=true;renderDemo('billing');notify(i.replacement?'Replacement-proof reminder recorded. Another is blocked for 24 hours.':'Payment reminder recorded. Another is blocked for 24 hours.')}
  if(a==='submit-proof'){const i=state.invoices[0];i.reference='FPS-330108';i.initiated='21 Sept 2026 · 11:02';i.auto=state.autoSent;i.status=state.autoSent?'issued':'review';i.date='22 Sept · just now';if(state.autoSent)i.receipt='R-2609-014';i.replacement=false;renderDemo('billing');notify(state.autoSent?'Sample proof accepted and receipt auto-sent. Bank matching remains pending.':'Sample proof added to the centre-review queue.')}
  if(a==='load-statement'){state.audit=true;renderDemo('billing')}
  if(a==='audit-exception'){openDialog('Unallocated bank credit',`<dl class="metadata"><div><dt>Bank posting date</dt><dd>22 Sept 2026</dd></div><div><dt>Description</dt><dd>FPS-772204 · CHAN TAI MAN · initiated 21 Sept</dd></div><div><dt>Credit</dt><dd>HK$500</dd></div><div><dt>Matching receipt</dt><dd>None in the sample records</dd></div></dl><p>Staff would investigate the payer, intended student and invoice before allocating this credit. The system should not guess a match from the amount alone.</p>`)}
  if(a==='franchise'){state.franchise=v;renderDemo('franchise')}
  if(a==='phase'){state.phase=Number(v);renderDemo('rollout')}
  if(a==='reset'){const d=b.dataset.demoId;if(d==='protection'){state.accessRole='teacher';state.printed=false;state.printCount=0}if(d==='library'){state.libStage='original';state.libValue='12.6'}if(d==='authoring'){state.builder=[{id:1,prompt:'12.6 ÷ 3 =',answer:'4.2'},{id:2,prompt:'8.4 ÷ 4 =',answer:'2.1'}];state.builderPublished=false;state.builderTitle='Division of decimals';state.builderView='tablet';renderDemo('teacher')}if(d==='teacher'){state.selected.clear();state.assigned=[];state.grade='P6';renderDemo('student')}if(d==='operations'){state.schedule={lesson:'wed',cancelled:false,pending:false};state.lessonSelected=false;state.scheduleReview=false;state.scheduleApplied=false;state.moveMode='one'}if(d==='billing'){state.invoices=originalInvoices();state.billTab='review';state.autoSent=true;state.search='';state.charge='all';state.month='all';state.audit=false}renderDemo(d);notify('Example reset.')}
 });
 document.addEventListener('change',e=>{const a=e.target.dataset.change,v=e.target.value;if(a==='access-role'){state.accessRole=v;state.printed=false;renderDemo('protection')}if(a==='grade'){state.grade=v;state.selected.clear();renderDemo('teacher')}if(a==='assignment-type')state.assignmentType=v;if(a==='move-mode'){state.moveMode=v;state.scheduleReview=false;state.scheduleApplied=false;renderDemo('operations');$('#demo-operations .regular-change').open=true}if(a==='auto-sent'){state.autoSent=e.target.checked;notify(state.autoSent?'Auto-sent enabled for future proof submissions.':'Manual review enabled for future proof submissions.')}if(a==='charge-filter'||a==='month-filter'){state[a==='charge-filter'?'charge':'month']=v;renderDemo('billing')}if(a==='bill-search'){state.search=v;renderDemo('billing')}});
 document.addEventListener('input',e=>{if(e.target.id==='worksheet-title'){state.builderTitle=e.target.value;state.builderPublished=false;const f=$('#demo-authoring .studio-footer');f.querySelector('span').textContent='Review content and layout before publishing.';f.querySelector('button').textContent='Review & publish';renderDemo('teacher')}if(e.target.dataset.change==='dividend'){state.libValue=e.target.value;$('#equation-preview').innerHTML=`${esc(e.target.value||'0')} ÷ 3 = <span class="answer-line"></span>`;$('#answer-preview').textContent='Teacher answer: '+Number((Number(e.target.value)/3).toFixed(2))}});
 document.addEventListener('dragstart',e=>{if(e.target.matches('.lesson-strip[draggable="true"]')){state.lessonSelected=true;e.dataTransfer.setData('text/plain','demo-alex-lesson');e.dataTransfer.effectAllowed='move'}});
 document.addEventListener('dragover',e=>{const t=e.target.closest('[data-drop]');if(t&&(t.dataset.hour==='16'||t.dataset.drop==='bin')){e.preventDefault();t.classList.add('drag-over')}});
 document.addEventListener('dragleave',e=>e.target.closest('[data-drop]')?.classList.remove('drag-over'));
 document.addEventListener('drop',e=>{const t=e.target.closest('[data-drop]');if(!t)return;e.preventDefault();t.classList.remove('drag-over');if(e.dataTransfer.getData('text/plain')!=='demo-alex-lesson')return;if(t.dataset.drop==='bin')recordLeave();else if(t.dataset.hour==='16')moveLesson(t.dataset.drop)});
 document.addEventListener('click',e=>{const t=e.target.closest('.calendar-cell[data-hour="16"]');if(t&&!e.target.closest('.lesson-strip')&&state.lessonSelected)moveLesson(t.dataset.drop)});
 document.addEventListener('keydown',e=>{const t=e.target.closest('.calendar-cell[data-hour="16"]');if(t&&e.target===t&&['Enter',' '].includes(e.key)){e.preventDefault();if(state.lessonSelected)moveLesson(t.dataset.drop);else notify('Select the lesson first.')}});
 window.addEventListener('resize',refreshInk);
}
function recordLeave(){state.schedule={lesson:'wed',cancelled:true,pending:true};state.lessonSelected=false;renderDemo('operations');notify('Leave recorded. The original lesson is crossed out and CS must arrange the make-up.')}
function moveLesson(day){if(state.schedule.pending){notify('Confirm the time with the parent using “Arrange agreed time”.');return}state.schedule={lesson:day,cancelled:day!=='wed',pending:false};state.lessonSelected=false;renderDemo('operations');notify('Lesson moved in the sample schedule.')}
